/* @lc app=leetcode id=3872 lang=kotlin */ class Solution { fun longestArithmetic(nums: IntArray): Int = nums.size.let { n -> IntArray(n).let { L -> IntArray(n).let { dL -> IntArray(n).let { R -> IntArray(n).let { dR -> (0 until n).forEach { i -> (if (i == 0) 1 else if (i == 1) 2 else if (nums[i] - nums[i - 1] == dL[i - 1]) L[i - 1] + 1 else 2).let { l -> L.set(i, l).also { dL[i] = if (i == 0) 0 else nums[i] - nums[i - 1] } } }.let { (n - 1 downTo 0).forEach { i -> (if (i == n - 1) 1 else if (i == n - 2) 2 else if (nums[i + 1] - nums[i] == dR[i + 1]) R[i + 1] + 1 else 2).let { l -> R.set(i, l).also { dR[i] = if (i == n - 1) 0 else nums[i + 1] - nums[i] } } } }.let { maxOf(L.max(), (0 until n).maxOf { j -> maxOf(if (j > 0) L[j - 1] + 1 else 0, if (j < n - 1) R[j + 1] + 1 else 0, if (j in 1..n - 2 && (nums[j + 1] - nums[j - 1]) % 2 == 0) ((nums[j + 1] - nums[j - 1]) / 2).let { d -> (if (L[j - 1] >= 2 && dL[j - 1] == d) L[j - 1] else 1) + 1 + (if (R[j + 1] >= 2 && dR[j + 1] == d) R[j + 1] else 1) } else 0) }) } } } } } } }